// Retry taxonomy — mirrors lib/ops/retry.ts, which is the tested specification.
const RETRYABLE = new Set(['network_timeout','dns_failure','connection_reset','http_408','http_429','http_500','http_502','http_503','http_504','db_connection_failure','ai_provider_unavailable','ai_rate_limited','storage_unavailable']);

const isRetryable = (code) => RETRYABLE.has(code);

const codeForHttpStatus = (s) => {
  if (s === 408) return 'http_408';
  if (s === 429) return 'http_429';
  if ([500,502,503,504].includes(s)) return 'http_' + s;
  if (s >= 500) return 'http_500';
  if (s === 401) return 'http_401';
  if (s === 403) return 'http_403';
  if (s === 404) return 'http_404';
  if (s === 410) return 'http_410';
  if (s >= 400) return 'http_400';
  return 'ok';
};

// Exponential backoff WITH JITTER. Without jitter a batch of sources that
// failed together would retry in lockstep forever, keeping the herd
// synchronised on whatever upstream knocked them over.
const backoffMs = (attempt, schedule) => {
  const s = (schedule && schedule.length) ? schedule : [5,15,45,120,360];
  const base = (s[Math.min(Math.max(attempt,1), s.length) - 1] || 5) * 60000;
  const spread = base * 0.2;
  return Math.max(1000, Math.round(base + (Math.random() * 2 - 1) * spread));
};

// ── RETRY SWEEP ────────────────────────────────────────────────────────────
// Runs every 15 minutes. Finds sources whose backoff has elapsed and decides,
// per source, whether another attempt is warranted or the job is dead.
//
// Idempotent: it only ever moves a source forward — either scheduling the next
// attempt or marking it dead. It never re-enqueues an item already published,
// because the Publishing Gate's hash check runs on every path.

const all = $input.all().map(i => i.json);
const settings = all.filter(r => typeof r.key === 'string');
const sources  = all.filter(r => typeof r.base_url === 'string');

const setting = (key, fallback) => {
  const row = settings.find(r => r.key === key);
  return row && row.value !== null && row.value !== undefined ? row.value : fallback;
};

const schedule = setting('ingestion.retry_backoff_minutes', [5,15,45,120,360]);
const maxAttempts = Array.isArray(schedule) ? schedule.length : 5;
const now = Date.now();

const toRetry = [];
const toKill = [];

for (const s of sources) {
  if (!s.active || s.config_status !== 'verified') continue;
  if (s.retry_attempt <= 0) continue;
  if (!s.next_retry_at || new Date(s.next_retry_at).getTime() > now) continue;

  const code = s.last_error_code || 'unknown_error';

  // A permanent error is not retried at all, however many attempts remain.
  // Retrying a 404 or a selector mismatch cannot succeed and only delays the
  // moment somebody notices.
  if (!isRetryable(code)) {
    toKill.push({ json: { source: s, reason: 'permanent_error', error_code: code } });
    continue;
  }

  if (s.retry_attempt >= maxAttempts) {
    toKill.push({ json: { source: s, reason: 'max_attempts_exhausted', error_code: code } });
    continue;
  }

  const next = s.retry_attempt + 1;
  toRetry.push({ json: {
    source: s,
    trigger_type: 'retry',
    dispatched_at: new Date().toISOString(),
    attempt_number: next,
    max_attempts: maxAttempts,
    next_backoff_ms: backoffMs(next, schedule),
  }});
}

console.log(JSON.stringify({ stage: 'retry_sweep', retrying: toRetry.length, dead: toKill.length }));
return [...toRetry, ...toKill];

// ── DEAD LETTER ────────────────────────────────────────────────────────────
// Builds the dead-letter row for a job that will not be retried again.
//
// The payload is written WITHOUT credentials: parser_config.headers can carry
// an API key for an authenticated feed, so it is stripped here. A CHECK
// constraint on the table rejects credential-shaped keys as a backstop.

const out = [];
for (const entry of $input.all()) {
  const e = entry.json;
  if (!e.reason) continue;               // this branch only handles deaths
  const s = e.source;

  const cfg = { ...(s.parser_config || {}) };
  delete cfg.headers;                    // never persist auth headers
  delete cfg.authorization;
  delete cfg.api_key;

  out.push({ json: {
    source_id: s.id,
    stage: 'fetch',
    item_url: s.feed_url || s.base_url,
    content_hash: null,
    error_code: e.error_code,
    error_message: (s.last_failure_reason || '').slice(0, 1000) || null,
    attempt_number: s.retry_attempt || 0,
    max_attempts: 5,
    first_attempt_at: s.first_attempt_at || null,
    last_attempt_at: s.last_failure_at || new Date().toISOString(),
    workflow_execution_id: String($execution.id),
    payload: { authority_ar: s.authority_ar, base_url: s.base_url, parser_type: s.parser_type, parser_config: cfg },
    state: 'open',
  }});
}
return out;

// ── HEALTH SNAPSHOT ────────────────────────────────────────────────────────
// Mirrors lib/ops/health.ts, which is the tested specification.
//
// Health measures whether the platform can RETRIEVE AND PROCESS a source.
// Duplicates, gate rejections on the merits, and empty runs NEVER reduce the
// score — a ministry that published nothing this week is quiet, not broken,
// and a dashboard that says otherwise trains people to ignore it.

const all = $input.all().map(i => i.json);
const settings = all.filter(r => typeof r.key === 'string');
const sources  = all.filter(r => typeof r.base_url === 'string');
const logs     = all.filter(r => typeof r.workflow_name === 'string');
const deads    = all.filter(r => typeof r.error_code === 'string' && r.state === 'open');

const setting = (key, fb) => {
  const row = settings.find(r => r.key === key);
  return row && row.value !== null && row.value !== undefined ? row.value : fb;
};

const failThreshold = Number(setting('ingestion.failure_alert_threshold', 5));
const defaultSilence = Number(setting('health.stale_after_minutes', 1440));
const cooldownMinutes = 180;
const now = Date.now();
const ratio = (n, d) => (d <= 0 ? null : Math.min(1, Math.max(0, n / d)));

const snapshots = [];
const alerts = [];

for (const s of sources) {
  const runs = logs.filter(l => l.source_id === s.id);
  const deadCount = deads.filter(d => d.source_id === s.id).length;

  let fetchOk = 0, extractionOk = 0, gateAttempts = 0, gateAccepted = 0, dupes = 0, durationTotal = 0;
  let aiAttempts = 0, aiOk = 0, lastItemFoundAt = null;

  for (const l of runs) {
    durationTotal += l.duration_ms || 0;
    if (l.status !== 'failed') fetchOk += 1;
    if ((l.items_fetched || 0) > 0) extractionOk += 1;

    const reasons = l.rejection_reasons || {};
    const aiFailures = (reasons.ai_parse_failure || 0) + (reasons.ai_invalid_output || 0);
    const items = (l.items_published || 0) + (l.items_rejected || 0);
    aiAttempts += items;
    aiOk += Math.max(0, items - aiFailures);

    gateAttempts += items;
    gateAccepted += l.items_published || 0;
    dupes += reasons.duplicate || 0;

    if ((l.items_published || 0) > 0 && (!lastItemFoundAt || l.started_at > lastItemFoundAt)) {
      lastItemFoundAt = l.started_at;
    }
  }

  const rates = {
    fetch: ratio(fetchOk, runs.length),
    extraction: ratio(extractionOk, fetchOk),
    ai: ratio(aiOk, aiAttempts),
    gate: ratio(gateAccepted, gateAttempts),
    dupe: ratio(dupes, gateAttempts),
  };

  const neverChecked = !s.last_run_at;
  const everSucceeded = !!s.last_success_at;
  const silence = s.max_silence_minutes || defaultSilence;

  // Staleness is measured from the last SUCCESSFUL CHECK, not the last item —
  // a source polled successfully that simply has nothing to say is healthy.
  const stale = everSucceeded && (now - new Date(s.last_success_at).getTime()) > silence * 60000;

  let score = 100;
  score -= Math.min(60, (s.consecutive_failures || 0) * 15);
  if (rates.fetch !== null) score -= (1 - rates.fetch) * 30;
  if (rates.extraction !== null) score -= (1 - rates.extraction) * 20;
  if (rates.ai !== null) score -= (1 - rates.ai) * 15;
  if (stale) score -= 20;
  if (deadCount > 0) score -= Math.min(15, deadCount * 5);
  score = Math.max(0, Math.min(100, Math.round(score)));

  let classification;
  if (!s.active) classification = 'disabled';
  else if (s.config_status !== 'verified') classification = 'unverified';
  else if (neverChecked) classification = 'never_run';
  else if ((s.consecutive_failures || 0) >= failThreshold || score < 40) classification = 'failing';
  else if ((s.consecutive_failures || 0) > 0 || score < 70) classification = 'degraded';
  else if (stale) classification = 'stale';
  else classification = 'healthy';

  snapshots.push({ json: {
    __kind: 'snapshot',
    source_id: s.id,
    classification,
    health_score: score,
    enabled: !!s.active,
    verified: s.config_status === 'verified',
    stale,
    last_checked_at: s.last_run_at,
    last_success_at: s.last_success_at,
    last_item_found_at: lastItemFoundAt,
    consecutive_failures: s.consecutive_failures || 0,
    dead_job_count: deadCount,
    window_runs: runs.length,
    fetch_success_rate: rates.fetch,
    extraction_success_rate: rates.extraction,
    ai_success_rate: rates.ai,
    gate_acceptance_rate: rates.gate,
    duplicate_rate: rates.dupe,
    avg_response_ms: runs.length ? Math.round(durationTotal / runs.length) : null,
    last_http_status: s.last_http_status || null,
    last_error_code: s.last_error_code || null,
    last_error_message: s.last_failure_reason || null,
  }});

  // ── alerting ────────────────────────────────────────────────────────────
  const previous = s.health_status;
  let kind = null;
  if (classification === 'failing' && previous !== 'failing') kind = 'source.failing';
  else if (classification === 'degraded' && previous !== 'degraded' && previous !== 'failing') kind = 'source.degraded';
  else if (classification === 'healthy' && (previous === 'degraded' || previous === 'failing')) kind = 'source.recovered';

  if (kind) {
    // Cooldown suppresses repeats of the SAME alert, so a flapping source does
    // not page anyone every fifteen minutes. Recovery is never suppressed —
    // leaving someone believing a source is still broken is worse than noise.
    const withinCooldown = kind !== 'source.recovered'
      && s.last_alert_at
      && s.last_alert_kind === kind
      && (now - new Date(s.last_alert_at).getTime()) < cooldownMinutes * 60000;

    if (!withinCooldown) {
      alerts.push({ json: {
        __kind: 'alert',
        event: kind,
        source_id: s.id,
        authority_ar: s.authority_ar,
        classification,
        previous,
        health_score: score,
        consecutive_failures: s.consecutive_failures || 0,
      }});
    }
  }
}

console.log(JSON.stringify({ stage: 'health_snapshot', snapshots: snapshots.length, alerts: alerts.length }));
return [...snapshots, ...alerts];

// Roll the classification, score and alert cooldown onto the source row so
// the dashboard and the next cooldown check read current state.
const snap = $input.first().json;
return [{ json: {
  id: snap.source_id,
  health_status: snap.classification,
  health_score: snap.health_score,
}}];

// Alert payload for the outbound signed event.
//
// Nothing sensitive: source identity, classification and counts only. No
// credentials, no headers, no raw payloads.
return $input.all().map(e => ({ json: {
  event: e.json.event,
  source_id: e.json.source_id,
  authority_ar: e.json.authority_ar,
  classification: e.json.classification,
  previous: e.json.previous,
  health_score: e.json.health_score,
  consecutive_failures: e.json.consecutive_failures,
  emitted_at: new Date().toISOString(),
}}));

// ── REQUEST VALIDATION ──────────────────────────────────────────────────────
// Mirrors lib/ops/dispatch.ts validateManualRunBody, the tested specification.
// Rejected here, before any source is touched, so the webhook answers 400
// instead of doing nothing or failing three nodes later. The webhook is
// reachable directly by anyone holding N8N_TRIGGER_SECRET, not only through
// the Next.js form, so it cannot trust that a caller already validated.

const body = $('Manual run webhook').first().json.body || {};
const SCOPES = ['source', 'country', 'all', 'url', 'replay', 'drain'];

const scope = body.scope;
let invalidReason = null;
if (typeof scope !== 'string' || !SCOPES.includes(scope)) invalidReason = 'invalid_scope';
else if (scope === 'source' && !body.source_id) invalidReason = 'missing_source_id';
else if (scope === 'country' && !body.country) invalidReason = 'missing_country';
else if (scope === 'url' && !body.url) invalidReason = 'missing_url';
else if (scope === 'replay' && !body.dead_letter_id) invalidReason = 'missing_dead_letter_id';

if (invalidReason) {
  return [{ json: { __valid: false, reason: invalidReason, correlation_id: body.correlation_id || null } }];
}

// correlation_id is always supplied by the Next.js caller (lib/ops/actions.ts);
// the fallback only covers a direct webhook call made without one.
const correlationId = body.correlation_id
  || ('m-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10));

return [{ json: {
  __valid: true,
  scope,
  source_id: body.source_id || null,
  country: body.country || null,
  url: body.url || null,
  dead_letter_id: body.dead_letter_id || null,
  force: !!body.force,
  correlation_id: correlationId,
  requested_by: body.requested_by || null,
  requested_at: body.requested_at || new Date().toISOString(),
}}];

// A malformed manual-run request — rejected before any source is touched.
const v = $input.first().json;
return [{ json: {
  ok: false,
  status: 'invalid_request',
  correlation_id: v.correlation_id || null,
  reason: v.reason,
  accepted_at: new Date().toISOString(),
}}];

// Idempotent replay: a correlation_id already accepted answers with the
// ORIGINAL outcome instead of resolving the scope (and dispatching) again.
//
// "Check existing dispatch" runs with alwaysOutputData, so a genuine
// zero-row result still arrives as one placeholder item with no
// correlation_id — filtered out here rather than trusted by item count.
const rows = $input.all().map(i => i.json).filter(r => r && r.correlation_id);
if (rows.length === 0) return [{ json: { __replay: false } }];
const r = rows[0];
return [{ json: {
  __replay: true,
  correlation_id: r.correlation_id,
  source_id: r.source_id,
  accepted_at: r.accepted_at,
  accepted_sources: r.accepted_sources || [],
  skipped_sources: r.skipped_sources || [],
}}];

// Reshapes the stored dispatch row into the same contract a fresh accept
// would return — same correlation_id, same accepted_at, same sources. This is
// what makes correlation_id an idempotency key, not just a tracing label.
const r = $input.first().json;
return [{ json: {
  ok: true,
  status: 'accepted',
  correlation_id: r.correlation_id,
  source_id: r.source_id,
  accepted_at: r.accepted_at,
  accepted_sources: r.accepted_sources,
  skipped_sources: r.skipped_sources,
}}];

// "Record dispatch" only writes the idempotency ledger; ITS output is the
// inserted row, not the response. Restore the response actually built for
// the caller, unaffected by whatever the insert (or its onError passthrough
// on a duplicate-key race) happened to return.
return [{ json: $('Build manual run response').first().json }];

// ── MANUAL RUN RESOLVER ────────────────────────────────────────────────────
// Resolves the requested scope to a source set and decides which are runnable
// now versus already locked. The resolved sources go into the SAME ingestion
// workflow the scheduler uses — there is no simplified manual path: a second
// pipeline would be a second set of rules to keep in step, and the one used
// in an emergency is the one least likely to be right.

const req = $('Validate request').first().json;
const all = $input.all().map(i => i.json).filter(r => typeof r.base_url === 'string');
const scope = req.scope;
const now = Date.now();

let selected = [];
if (scope === 'source') selected = all.filter(s => s.id === req.source_id);
else if (scope === 'country') selected = all.filter(s => s.country === req.country);
else if (scope === 'all' || scope === 'drain') selected = all;
else if (scope === 'url' || scope === 'replay') {
  selected = req.source_id ? all.filter(s => s.id === req.source_id) : all;
}

// Only what the scheduler would run anyway. A manual run cannot activate a
// source the database refuses to activate.
selected = selected.filter(s => s.active && s.config_status === 'verified' && s.parser_type !== 'unknown');

const runnable = [];
const skipped = [];

for (const s of selected) {
  const locked = s.lock_expires_at && new Date(s.lock_expires_at).getTime() > now;
  if (locked && !req.force) {
    skipped.push({ json: { skipped: true, reason: 'already_running', source_id: s.id, authority_ar: s.authority_ar } });
    continue;
  }
  runnable.push({ json: {
    source: s,
    trigger_type: 'manual',
    dispatched_at: new Date().toISOString(),
    correlation_id: req.correlation_id,
    requested_by: req.requested_by,
    single_url: scope === 'url' ? req.url : null,
    dead_letter_id: scope === 'replay' ? req.dead_letter_id : null,
    forced: !!req.force,
  }});
}

console.log(JSON.stringify({
  stage: 'manual_run', correlation_id: req.correlation_id,
  scope, runnable: runnable.length, skipped: skipped.length,
}));

if (runnable.length === 0 && skipped.length === 0) {
  // Nothing matched the requested scope at all: distinguish "no such source"
  // from "no active/verified sources for this scope" so the webhook can
  // answer 404 vs 200 instead of silently answering with nothing.
  const requestedButMissing =
    (scope === 'source' || scope === 'url' || scope === 'replay') &&
    req.source_id &&
    !all.some((s) => s.id === req.source_id);

  return [{ json: {
    skipped: true,
    not_found: requestedButMissing,
    reason: requestedButMissing ? 'source_not_found' : 'no_matching_sources',
    source_id: req.source_id || null,
    scope,
  } }];
}

return [...runnable, ...skipped];

// ── MANUAL RUN RESPONSE ─────────────────────────────────────────────────────
// Aggregates the resolved sources (dispatched and skipped) into the single
// response contract returned to the caller. Mirrors lib/ops/dispatch.ts —
// resolveManualRun / foldDispatchFailures — the tested specification.

const req = $('Validate request').first().json;
const items = $input.all().map(i => i.json);
const now = new Date().toISOString();

// A request whose scope matched nothing, or named a source that does not
// exist, arrives as ONE marker item.
if (items.length === 1 && items[0].skipped && (items[0].reason === 'no_matching_sources' || items[0].not_found)) {
  const marker = items[0];
  if (marker.not_found) {
    return [{ json: {
      ok: false, status: 'rejected', correlation_id: req.correlation_id,
      source_id: marker.source_id || null, accepted_at: now, reason: 'source_not_found',
    }}];
  }
  return [{ json: {
    ok: true, status: 'skipped', correlation_id: req.correlation_id,
    source_id: req.source_id, accepted_at: now, reason: 'no_matching_sources',
  }}];
}

const accepted = [];
const skipped = [];

for (const e of items) {
  if (e.skipped) {
    skipped.push({ source_id: e.source_id, reason: e.reason || 'already_running' });
    continue;
  }
  // n8n leaves .error on an item that failed to even start when the dispatch
  // node's onError is continueRegularOutput — reported, not silently lost.
  if (e.error) {
    skipped.push({ source_id: (e.source && e.source.id) || null, reason: 'dispatch_failed' });
    continue;
  }
  accepted.push(e.source.id);
}

// Only when EVERY accepted candidate failed to start does the response
// become a genuine dispatch failure (500). One bad source id in a
// country/all batch must not turn a mostly-successful run into a 500.
if (accepted.length === 0 && skipped.length > 0 && skipped.every(s => s.reason === 'dispatch_failed')) {
  return [{ json: {
    ok: false, status: 'failed', correlation_id: req.correlation_id,
    source_id: req.source_id, accepted_at: now, reason: 'dispatch_failed', skipped_sources: skipped,
  }}];
}

if (accepted.length === 0) {
  return [{ json: {
    ok: true, status: 'skipped', correlation_id: req.correlation_id,
    source_id: req.source_id, accepted_at: now, reason: 'already_running', skipped_sources: skipped,
  }}];
}

return [{ json: {
  ok: true,
  status: 'accepted',
  correlation_id: req.correlation_id,
  source_id: req.scope === 'source' ? (req.source_id || accepted[0]) : (accepted.length === 1 ? accepted[0] : null),
  accepted_at: now,
  accepted_sources: accepted,
  skipped_sources: skipped,
  scope: req.scope,
}}];

// Shapes the accepted outcome into exactly the manual_run_dispatches
// columns — the idempotency ledger a retried correlation_id is answered from.
const r = $input.first().json;
const req = $('Validate request').first().json;
return [{ json: {
  correlation_id: r.correlation_id,
  source_id: r.source_id,
  scope: r.scope,
  accepted_sources: r.accepted_sources || [],
  skipped_sources: r.skipped_sources || [],
  accepted_at: r.accepted_at,
  requested_by: req.requested_by,
}}];

// Retry taxonomy — mirrors lib/ops/retry.ts, which is the tested specification.
const RETRYABLE = new Set(['network_timeout','dns_failure','connection_reset','http_408','http_429','http_500','http_502','http_503','http_504','db_connection_failure','ai_provider_unavailable','ai_rate_limited','storage_unavailable']);

const isRetryable = (code) => RETRYABLE.has(code);

const codeForHttpStatus = (s) => {
  if (s === 408) return 'http_408';
  if (s === 429) return 'http_429';
  if ([500,502,503,504].includes(s)) return 'http_' + s;
  if (s >= 500) return 'http_500';
  if (s === 401) return 'http_401';
  if (s === 403) return 'http_403';
  if (s === 404) return 'http_404';
  if (s === 410) return 'http_410';
  if (s >= 400) return 'http_400';
  return 'ok';
};

// Exponential backoff WITH JITTER. Without jitter a batch of sources that
// failed together would retry in lockstep forever, keeping the herd
// synchronised on whatever upstream knocked them over.
const backoffMs = (attempt, schedule) => {
  const s = (schedule && schedule.length) ? schedule : [5,15,45,120,360];
  const base = (s[Math.min(Math.max(attempt,1), s.length) - 1] || 5) * 60000;
  const spread = base * 0.2;
  return Math.max(1000, Math.round(base + (Math.random() * 2 - 1) * spread));
};

// ── RETRY SWEEP ────────────────────────────────────────────────────────────
// Runs every 15 minutes. Finds sources whose backoff has elapsed and decides,
// per source, whether another attempt is warranted or the job is dead.
//
// Idempotent: it only ever moves a source forward — either scheduling the next
// attempt or marking it dead. It never re-enqueues an item already published,
// because the Publishing Gate's hash check runs on every path.

const all = $input.all().map(i => i.json);
const settings = all.filter(r => typeof r.key === 'string');
const sources  = all.filter(r => typeof r.base_url === 'string');

const setting = (key, fallback) => {
  const row = settings.find(r => r.key === key);
  return row && row.value !== null && row.value !== undefined ? row.value : fallback;
};

const schedule = setting('ingestion.retry_backoff_minutes', [5,15,45,120,360]);
const maxAttempts = Array.isArray(schedule) ? schedule.length : 5;
const now = Date.now();

const toRetry = [];
const toKill = [];

for (const s of sources) {
  if (!s.active || s.config_status !== 'verified') continue;
  if (s.retry_attempt <= 0) continue;
  if (!s.next_retry_at || new Date(s.next_retry_at).getTime() > now) continue;

  const code = s.last_error_code || 'unknown_error';

  // A permanent error is not retried at all, however many attempts remain.
  // Retrying a 404 or a selector mismatch cannot succeed and only delays the
  // moment somebody notices.
  if (!isRetryable(code)) {
    toKill.push({ json: { source: s, reason: 'permanent_error', error_code: code } });
    continue;
  }

  if (s.retry_attempt >= maxAttempts) {
    toKill.push({ json: { source: s, reason: 'max_attempts_exhausted', error_code: code } });
    continue;
  }

  const next = s.retry_attempt + 1;
  toRetry.push({ json: {
    source: s,
    trigger_type: 'retry',
    dispatched_at: new Date().toISOString(),
    attempt_number: next,
    max_attempts: maxAttempts,
    next_backoff_ms: backoffMs(next, schedule),
  }});
}

console.log(JSON.stringify({ stage: 'retry_sweep', retrying: toRetry.length, dead: toKill.length }));
return [...toRetry, ...toKill];

// ── DEAD LETTER ────────────────────────────────────────────────────────────
// Builds the dead-letter row for a job that will not be retried again.
//
// The payload is written WITHOUT credentials: parser_config.headers can carry
// an API key for an authenticated feed, so it is stripped here. A CHECK
// constraint on the table rejects credential-shaped keys as a backstop.

const out = [];
for (const entry of $input.all()) {
  const e = entry.json;
  if (!e.reason) continue;               // this branch only handles deaths
  const s = e.source;

  const cfg = { ...(s.parser_config || {}) };
  delete cfg.headers;                    // never persist auth headers
  delete cfg.authorization;
  delete cfg.api_key;

  out.push({ json: {
    source_id: s.id,
    stage: 'fetch',
    item_url: s.feed_url || s.base_url,
    content_hash: null,
    error_code: e.error_code,
    error_message: (s.last_failure_reason || '').slice(0, 1000) || null,
    attempt_number: s.retry_attempt || 0,
    max_attempts: 5,
    first_attempt_at: s.first_attempt_at || null,
    last_attempt_at: s.last_failure_at || new Date().toISOString(),
    workflow_execution_id: String($execution.id),
    payload: { authority_ar: s.authority_ar, base_url: s.base_url, parser_type: s.parser_type, parser_config: cfg },
    state: 'open',
  }});
}
return out;

// ── HEALTH SNAPSHOT ────────────────────────────────────────────────────────
// Mirrors lib/ops/health.ts, which is the tested specification.
//
// Health measures whether the platform can RETRIEVE AND PROCESS a source.
// Duplicates, gate rejections on the merits, and empty runs NEVER reduce the
// score — a ministry that published nothing this week is quiet, not broken,
// and a dashboard that says otherwise trains people to ignore it.

const all = $input.all().map(i => i.json);
const settings = all.filter(r => typeof r.key === 'string');
const sources  = all.filter(r => typeof r.base_url === 'string');
const logs     = all.filter(r => typeof r.workflow_name === 'string');
const deads    = all.filter(r => typeof r.error_code === 'string' && r.state === 'open');

const setting = (key, fb) => {
  const row = settings.find(r => r.key === key);
  return row && row.value !== null && row.value !== undefined ? row.value : fb;
};

const failThreshold = Number(setting('ingestion.failure_alert_threshold', 5));
const defaultSilence = Number(setting('health.stale_after_minutes', 1440));
const cooldownMinutes = 180;
const now = Date.now();
const ratio = (n, d) => (d <= 0 ? null : Math.min(1, Math.max(0, n / d)));

const snapshots = [];
const alerts = [];

for (const s of sources) {
  const runs = logs.filter(l => l.source_id === s.id);
  const deadCount = deads.filter(d => d.source_id === s.id).length;

  let fetchOk = 0, extractionOk = 0, gateAttempts = 0, gateAccepted = 0, dupes = 0, durationTotal = 0;
  let aiAttempts = 0, aiOk = 0, lastItemFoundAt = null;

  for (const l of runs) {
    durationTotal += l.duration_ms || 0;
    if (l.status !== 'failed') fetchOk += 1;
    if ((l.items_fetched || 0) > 0) extractionOk += 1;

    const reasons = l.rejection_reasons || {};
    const aiFailures = (reasons.ai_parse_failure || 0) + (reasons.ai_invalid_output || 0);
    const items = (l.items_published || 0) + (l.items_rejected || 0);
    aiAttempts += items;
    aiOk += Math.max(0, items - aiFailures);

    gateAttempts += items;
    gateAccepted += l.items_published || 0;
    dupes += reasons.duplicate || 0;

    if ((l.items_published || 0) > 0 && (!lastItemFoundAt || l.started_at > lastItemFoundAt)) {
      lastItemFoundAt = l.started_at;
    }
  }

  const rates = {
    fetch: ratio(fetchOk, runs.length),
    extraction: ratio(extractionOk, fetchOk),
    ai: ratio(aiOk, aiAttempts),
    gate: ratio(gateAccepted, gateAttempts),
    dupe: ratio(dupes, gateAttempts),
  };

  const neverChecked = !s.last_run_at;
  const everSucceeded = !!s.last_success_at;
  const silence = s.max_silence_minutes || defaultSilence;

  // Staleness is measured from the last SUCCESSFUL CHECK, not the last item —
  // a source polled successfully that simply has nothing to say is healthy.
  const stale = everSucceeded && (now - new Date(s.last_success_at).getTime()) > silence * 60000;

  let score = 100;
  score -= Math.min(60, (s.consecutive_failures || 0) * 15);
  if (rates.fetch !== null) score -= (1 - rates.fetch) * 30;
  if (rates.extraction !== null) score -= (1 - rates.extraction) * 20;
  if (rates.ai !== null) score -= (1 - rates.ai) * 15;
  if (stale) score -= 20;
  if (deadCount > 0) score -= Math.min(15, deadCount * 5);
  score = Math.max(0, Math.min(100, Math.round(score)));

  let classification;
  if (!s.active) classification = 'disabled';
  else if (s.config_status !== 'verified') classification = 'unverified';
  else if (neverChecked) classification = 'never_run';
  else if ((s.consecutive_failures || 0) >= failThreshold || score < 40) classification = 'failing';
  else if ((s.consecutive_failures || 0) > 0 || score < 70) classification = 'degraded';
  else if (stale) classification = 'stale';
  else classification = 'healthy';

  snapshots.push({ json: {
    __kind: 'snapshot',
    source_id: s.id,
    classification,
    health_score: score,
    enabled: !!s.active,
    verified: s.config_status === 'verified',
    stale,
    last_checked_at: s.last_run_at,
    last_success_at: s.last_success_at,
    last_item_found_at: lastItemFoundAt,
    consecutive_failures: s.consecutive_failures || 0,
    dead_job_count: deadCount,
    window_runs: runs.length,
    fetch_success_rate: rates.fetch,
    extraction_success_rate: rates.extraction,
    ai_success_rate: rates.ai,
    gate_acceptance_rate: rates.gate,
    duplicate_rate: rates.dupe,
    avg_response_ms: runs.length ? Math.round(durationTotal / runs.length) : null,
    last_http_status: s.last_http_status || null,
    last_error_code: s.last_error_code || null,
    last_error_message: s.last_failure_reason || null,
  }});

  // ── alerting ────────────────────────────────────────────────────────────
  const previous = s.health_status;
  let kind = null;
  if (classification === 'failing' && previous !== 'failing') kind = 'source.failing';
  else if (classification === 'degraded' && previous !== 'degraded' && previous !== 'failing') kind = 'source.degraded';
  else if (classification === 'healthy' && (previous === 'degraded' || previous === 'failing')) kind = 'source.recovered';

  if (kind) {
    // Cooldown suppresses repeats of the SAME alert, so a flapping source does
    // not page anyone every fifteen minutes. Recovery is never suppressed —
    // leaving someone believing a source is still broken is worse than noise.
    const withinCooldown = kind !== 'source.recovered'
      && s.last_alert_at
      && s.last_alert_kind === kind
      && (now - new Date(s.last_alert_at).getTime()) < cooldownMinutes * 60000;

    if (!withinCooldown) {
      alerts.push({ json: {
        __kind: 'alert',
        event: kind,
        source_id: s.id,
        authority_ar: s.authority_ar,
        classification,
        previous,
        health_score: score,
        consecutive_failures: s.consecutive_failures || 0,
      }});
    }
  }
}

console.log(JSON.stringify({ stage: 'health_snapshot', snapshots: snapshots.length, alerts: alerts.length }));
return [...snapshots, ...alerts];

// Roll the classification, score and alert cooldown onto the source row so
// the dashboard and the next cooldown check read current state.
const snap = $input.first().json;
return [{ json: {
  id: snap.source_id,
  health_status: snap.classification,
  health_score: snap.health_score,
}}];

// Alert payload for the outbound signed event.
//
// Nothing sensitive: source identity, classification and counts only. No
// credentials, no headers, no raw payloads.
return $input.all().map(e => ({ json: {
  event: e.json.event,
  source_id: e.json.source_id,
  authority_ar: e.json.authority_ar,
  classification: e.json.classification,
  previous: e.json.previous,
  health_score: e.json.health_score,
  consecutive_failures: e.json.consecutive_failures,
  emitted_at: new Date().toISOString(),
}}));

// ── REQUEST VALIDATION ──────────────────────────────────────────────────────
// Mirrors lib/ops/dispatch.ts validateManualRunBody, the tested specification.
// Rejected here, before any source is touched, so the webhook answers 400
// instead of doing nothing or failing three nodes later. The webhook is
// reachable directly by anyone holding N8N_TRIGGER_SECRET, not only through
// the Next.js form, so it cannot trust that a caller already validated.

const body = $('Manual run webhook').first().json.body || {};
const SCOPES = ['source', 'country', 'all', 'url', 'replay', 'drain'];

const scope = body.scope;
let invalidReason = null;
if (typeof scope !== 'string' || !SCOPES.includes(scope)) invalidReason = 'invalid_scope';
else if (scope === 'source' && !body.source_id) invalidReason = 'missing_source_id';
else if (scope === 'country' && !body.country) invalidReason = 'missing_country';
else if (scope === 'url' && !body.url) invalidReason = 'missing_url';
else if (scope === 'replay' && !body.dead_letter_id) invalidReason = 'missing_dead_letter_id';

if (invalidReason) {
  return [{ json: { __valid: false, reason: invalidReason, correlation_id: body.correlation_id || null } }];
}

// correlation_id is always supplied by the Next.js caller (lib/ops/actions.ts);
// the fallback only covers a direct webhook call made without one.
const correlationId = body.correlation_id
  || ('m-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10));

return [{ json: {
  __valid: true,
  scope,
  source_id: body.source_id || null,
  country: body.country || null,
  url: body.url || null,
  dead_letter_id: body.dead_letter_id || null,
  force: !!body.force,
  correlation_id: correlationId,
  requested_by: body.requested_by || null,
  requested_at: body.requested_at || new Date().toISOString(),
}}];

// A malformed manual-run request — rejected before any source is touched.
const v = $input.first().json;
return [{ json: {
  ok: false,
  status: 'invalid_request',
  correlation_id: v.correlation_id || null,
  reason: v.reason,
  accepted_at: new Date().toISOString(),
}}];

// Idempotent replay: a correlation_id already accepted answers with the
// ORIGINAL outcome instead of resolving the scope (and dispatching) again.
//
// "Check existing dispatch" runs with alwaysOutputData, so a genuine
// zero-row result still arrives as one placeholder item with no
// correlation_id — filtered out here rather than trusted by item count.
const rows = $input.all().map(i => i.json).filter(r => r && r.correlation_id);
if (rows.length === 0) return [{ json: { __replay: false } }];
const r = rows[0];
return [{ json: {
  __replay: true,
  correlation_id: r.correlation_id,
  source_id: r.source_id,
  accepted_at: r.accepted_at,
  accepted_sources: r.accepted_sources || [],
  skipped_sources: r.skipped_sources || [],
}}];

// Reshapes the stored dispatch row into the same contract a fresh accept
// would return — same correlation_id, same accepted_at, same sources. This is
// what makes correlation_id an idempotency key, not just a tracing label.
const r = $input.first().json;
return [{ json: {
  ok: true,
  status: 'accepted',
  correlation_id: r.correlation_id,
  source_id: r.source_id,
  accepted_at: r.accepted_at,
  accepted_sources: r.accepted_sources,
  skipped_sources: r.skipped_sources,
}}];

// "Record dispatch" only writes the idempotency ledger; ITS output is the
// inserted row, not the response. Restore the response actually built for
// the caller, unaffected by whatever the insert (or its onError passthrough
// on a duplicate-key race) happened to return.
return [{ json: $('Build manual run response').first().json }];

// ── MANUAL RUN RESOLVER ────────────────────────────────────────────────────
// Resolves the requested scope to a source set and decides which are runnable
// now versus already locked. The resolved sources go into the SAME ingestion
// workflow the scheduler uses — there is no simplified manual path: a second
// pipeline would be a second set of rules to keep in step, and the one used
// in an emergency is the one least likely to be right.

const req = $('Validate request').first().json;
const all = $input.all().map(i => i.json).filter(r => typeof r.base_url === 'string');
const scope = req.scope;
const now = Date.now();

let selected = [];
if (scope === 'source') selected = all.filter(s => s.id === req.source_id);
else if (scope === 'country') selected = all.filter(s => s.country === req.country);
else if (scope === 'all' || scope === 'drain') selected = all;
else if (scope === 'url' || scope === 'replay') {
  selected = req.source_id ? all.filter(s => s.id === req.source_id) : all;
}

// Only what the scheduler would run anyway. A manual run cannot activate a
// source the database refuses to activate.
selected = selected.filter(s => s.active && s.config_status === 'verified' && s.parser_type !== 'unknown');

const runnable = [];
const skipped = [];

for (const s of selected) {
  const locked = s.lock_expires_at && new Date(s.lock_expires_at).getTime() > now;
  if (locked && !req.force) {
    skipped.push({ json: { skipped: true, reason: 'already_running', source_id: s.id, authority_ar: s.authority_ar } });
    continue;
  }
  runnable.push({ json: {
    source: s,
    trigger_type: 'manual',
    dispatched_at: new Date().toISOString(),
    correlation_id: req.correlation_id,
    requested_by: req.requested_by,
    single_url: scope === 'url' ? req.url : null,
    dead_letter_id: scope === 'replay' ? req.dead_letter_id : null,
    forced: !!req.force,
  }});
}

console.log(JSON.stringify({
  stage: 'manual_run', correlation_id: req.correlation_id,
  scope, runnable: runnable.length, skipped: skipped.length,
}));

if (runnable.length === 0 && skipped.length === 0) {
  // Nothing matched the requested scope at all: distinguish "no such source"
  // from "no active/verified sources for this scope" so the webhook can
  // answer 404 vs 200 instead of silently answering with nothing.
  const requestedButMissing =
    (scope === 'source' || scope === 'url' || scope === 'replay') &&
    req.source_id &&
    !all.some((s) => s.id === req.source_id);

  return [{ json: {
    skipped: true,
    not_found: requestedButMissing,
    reason: requestedButMissing ? 'source_not_found' : 'no_matching_sources',
    source_id: req.source_id || null,
    scope,
  } }];
}

return [...runnable, ...skipped];

// ── MANUAL RUN RESPONSE ─────────────────────────────────────────────────────
// Aggregates the resolved sources (dispatched and skipped) into the single
// response contract returned to the caller. Mirrors lib/ops/dispatch.ts —
// resolveManualRun / foldDispatchFailures — the tested specification.

const req = $('Validate request').first().json;
const items = $input.all().map(i => i.json);
const now = new Date().toISOString();

// A request whose scope matched nothing, or named a source that does not
// exist, arrives as ONE marker item.
if (items.length === 1 && items[0].skipped && (items[0].reason === 'no_matching_sources' || items[0].not_found)) {
  const marker = items[0];
  if (marker.not_found) {
    return [{ json: {
      ok: false, status: 'rejected', correlation_id: req.correlation_id,
      source_id: marker.source_id || null, accepted_at: now, reason: 'source_not_found',
    }}];
  }
  return [{ json: {
    ok: true, status: 'skipped', correlation_id: req.correlation_id,
    source_id: req.source_id, accepted_at: now, reason: 'no_matching_sources',
  }}];
}

const accepted = [];
const skipped = [];

for (const e of items) {
  if (e.skipped) {
    skipped.push({ source_id: e.source_id, reason: e.reason || 'already_running' });
    continue;
  }
  // n8n leaves .error on an item that failed to even start when the dispatch
  // node's onError is continueRegularOutput — reported, not silently lost.
  if (e.error) {
    skipped.push({ source_id: (e.source && e.source.id) || null, reason: 'dispatch_failed' });
    continue;
  }
  accepted.push(e.source.id);
}

// Only when EVERY accepted candidate failed to start does the response
// become a genuine dispatch failure (500). One bad source id in a
// country/all batch must not turn a mostly-successful run into a 500.
if (accepted.length === 0 && skipped.length > 0 && skipped.every(s => s.reason === 'dispatch_failed')) {
  return [{ json: {
    ok: false, status: 'failed', correlation_id: req.correlation_id,
    source_id: req.source_id, accepted_at: now, reason: 'dispatch_failed', skipped_sources: skipped,
  }}];
}

if (accepted.length === 0) {
  return [{ json: {
    ok: true, status: 'skipped', correlation_id: req.correlation_id,
    source_id: req.source_id, accepted_at: now, reason: 'already_running', skipped_sources: skipped,
  }}];
}

return [{ json: {
  ok: true,
  status: 'accepted',
  correlation_id: req.correlation_id,
  source_id: req.scope === 'source' ? (req.source_id || accepted[0]) : (accepted.length === 1 ? accepted[0] : null),
  accepted_at: now,
  accepted_sources: accepted,
  skipped_sources: skipped,
  scope: req.scope,
}}];

// Shapes the accepted outcome into exactly the manual_run_dispatches
// columns — the idempotency ledger a retried correlation_id is answered from.
const r = $input.first().json;
const req = $('Validate request').first().json;
return [{ json: {
  correlation_id: r.correlation_id,
  source_id: r.source_id,
  scope: r.scope,
  accepted_sources: r.accepted_sources || [],
  skipped_sources: r.skipped_sources || [],
  accepted_at: r.accepted_at,
  requested_by: req.requested_by,
}}];
